FHQ Treap（无旋 Treap）.code:
struct Node{ int ch[2],pri,sz,val; } tr[N];
void split(int rt,int k,int&a,int&b){ if(!rt){a=b=0;return;} if(tr[tr[rt].ch[0]].sz>=k){ split(tr[rt].ch[0],k,a,tr[rt].ch[0]); b=rt; } else { split(tr[rt].ch[1],k-tr[tr[rt].ch[0]].sz-1,tr[rt].ch[1],b); a=rt; } push(rt); }
int merge(int a,int b){ if(!a||!b) return a+b; if(tr[a].pri<tr[b].pri){ tr[a].ch[1]=merge(tr[a].ch[1],b); push(a); return a; } else { tr[b].ch[0]=merge(a,tr[b].ch[0]); push(b); return b; } }

可撤销并查集.code:
struct DSU{ int fa[N],sz[N]; vector<tuple<int,int,int>> st;
 int find(int x){ while(fa[x]!=x) x=fa[x]; return x; }
 void unite(int a,int b){ a=find(a);b=find(b); if(a==b){st.push({-1,0,0});return;} if(sz[a]<sz[b]) swap(a,b); st.push({a,b,sz[a]}); fa[b]=a; sz[a]+=sz[b]; }
 void rollback(){ auto [a,b,s]=st.back(); st.pop_back(); if(a<0) return; fa[b]=b; sz[a]=s; } };

