SAM（后缀自动机）.code:
struct SAM{ int ch[N][26],link[N],len[N],last=1,tot=1;
 void extend(int c){ int p=last, np=++tot; len[np]=len[p]+1;
  for(;p&&!ch[p][c];p=link[p]) ch[p][c]=np;
  if(!p) link[np]=1; else { int q=ch[p][c]; if(len[p]+1==len[q]) link[np]=q; else { int nq=++tot; len[nq]=len[p]+1; memcpy(ch[nq],ch[q],sizeof ch[q]); link[nq]=link[q]; for(;p&&ch[p][c]==q;p=link[p]) ch[p][c]=nq; link[q]=link[np]=nq; } } last=np; } };

