 for(auto a:p){ while(h.size()>=2 && cross(h[h.size()-2],h.back(),a)<=0) h.pop_back(); h.push_back(a); }
 int low=h.size(); for(int i=p.size()-2;i>=0;--i){ while(h.size()>low && cross(h[h.size()-2],h.back(),p[i])<=0) h.pop_back(); h.push_back(p[i]); } h.pop_back(); return h; }

