Link-Cut Tree (LCT).code:
void access(int x){ for(int y=0;x;y=x,x=fa[x]) splay(x), ch[x][1]=y, push(x); }
void makeroot(int x){ access(x); splay(x); rev[x]^=1; }
int findroot(int x){ access(x); splay(x); while(ch[x][0]) push(x), x=ch[x][0]; splay(x); return x; }
void split(int x,int y){ makeroot(x); access(y); splay(y); }
void link(int x,int y){ makeroot(x); if(findroot(y)!=x) fa[x]=y; }
void cut(int x,int y){ split(x,y); if(ch[y][0]==x && !ch[x][1]) ch[y][0]=fa[x]=0; }

